import java.util.Scanner;

public class Main {
    static long fn, fd;
    static long ra, rb;

    static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static void evaluate(long x, long y, long b, long a) {
        if (a < 0) return;
        long kkk = gcd(a, b);
        a /= kkk;
        b /= kkk;
        long n = Math.abs(b * x - a * y);
        long d = b * y;
        long g = gcd(n, d);
        n /= g;
        d /= g;
        if (n * fd < fn * d) {
            fn = n;
            fd = d;
            ra = a;
            rb = b;
            return;
        }
